/**
 * What a first visit downloads, and what a click then has to wait for (E28).
 *
 * Measured against the deployed build (`main`, `41ab940`) with a clean profile and the WebSocket
 * stubbed before boot, so no layout is restored: `App-B1dbS6Vf.js` was **76 406 B on the wire**,
 * the single biggest thing a new visitor downloaded — bigger than either webfont. Attributing its
 * generated bytes to sources (the build's own sourcemap) put three whole surfaces in there that
 * **no first visit can reach**: the notes and agents panels (the side panel is closed in a fresh
 * pane and stays closed until somebody opens it) and the routines board (a `<dialog>` that is not
 * open). Together with the drawer's own queue and channels they were ~45 KB of compiled code
 * shipped to everybody to serve nobody.
 *
 * And the split is not free, which is why this file exists. `bind:this` binds when the component
 * mounts, and a lazy component mounts when its chunk lands — *after* the `tick()` that the opener
 * awaits. Measured A/B on the same probe, opening the panel on a real session: the naive split
 * rendered the panel (chunk fetched, textarea present) and left the focus on the composer at
 * every one of five samples up to 3.5 s, so `Ctrl/⌘ ⇧ .` put you in the notes and dropped your
 * keystrokes into the chat. Baseline and the fix both land the focus in the textarea on the first
 * try. The assertions below pin the wiring, because "there is an `import()` somewhere" passes
 * just as happily against the broken version.
 */
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { deliverSideFocus, type SideTab } from "../web/src/lib/sidePanelFocus";

const pane = readFileSync(join(import.meta.dir, "..", "web", "src", "lib", "components", "ChatPane.svelte"), "utf8");
const app = readFileSync(join(import.meta.dir, "..", "web", "src", "App.svelte"), "utf8");

describe("a focus request survives a side panel whose chunk is still in flight", () => {
  test("a request aimed at a panel that is not mounted is kept, not spent", () => {
    // THE defect: the panel arrives a round trip later, so there is nobody to take the focus yet.
    const out = deliverSideFocus("notes", { notes: null, agents: null, terminal: null });
    expect(out.focused).toBe(false);
    expect(out.request).toBe("notes");
  });

  test("the kept request is delivered as soon as the panel binds, and only then is it spent", () => {
    let got = 0;
    const panels = { notes: null as { focus: () => void } | null };
    // First attempt: chunk still flying.
    expect(deliverSideFocus("notes", panels).request).toBe("notes");
    // The `{#await}` block binds the component.
    panels.notes = { focus: () => got++ };
    const second = deliverSideFocus(panels ? "notes" : "notes", panels);
    expect(second.focused).toBe(true);
    expect(got).toBe(1);
    expect(second.request).toBeNull();
    // And it is spent: asking again does not steal the focus back.
    expect(deliverSideFocus(second.request, panels).focused).toBe(false);
  });

  test("a request goes to the panel it names, and only to it", () => {
    let notes = 0, agents = 0, terminal = 0;
    const panels = { notes: { focus: () => notes++ }, agents: { focus: () => agents++ }, terminal: { focus: () => terminal++ } };
    for (const tab of ["notes", "agents", "terminal"] as SideTab[]) {
      expect(deliverSideFocus(tab, panels).focused).toBe(true);
    }
    expect([notes, agents, terminal]).toEqual([1, 1, 1]);
  });

  test("no request moves nothing and crashes nothing", () => {
    let n = 0;
    expect(deliverSideFocus(null, { notes: { focus: () => n++ } })).toEqual({ request: null, focused: false });
    expect(n).toBe(0);
  });

  test("a panel registered as undefined counts as not mounted", () => {
    // `bind:this` on a branch that has not rendered leaves the holder undefined, not null.
    expect(deliverSideFocus("agents", { agents: undefined }).request).toBe("agents");
  });
});

describe("the two side panels are not in the boot chunk", () => {
  test("both are reached through a dynamic import", () => {
    expect(pane).toMatch(/const NotesPanel = \(\) => import\("\.\/NotesPanel\.svelte"\)/);
    expect(pane).toMatch(/const AgentsPanel = \(\) => import\("\.\/AgentsPanel\.svelte"\)/);
    // The static import is exactly what put them in the chunk.
    expect(pane).not.toMatch(/^\s*import NotesPanel from/m);
    expect(pane).not.toMatch(/^\s*import AgentsPanel from/m);
  });

  test("every place that used to focus a panel directly now goes through the latch", () => {
    // `void tick().then(() => notes?.focus())` is the shape that loses the focus: tick resolves
    // before the chunk lands. Three call sites had it.
    expect(pane).not.toMatch(/\(\) => notes\?\.focus\(\)/);
    expect(pane).not.toMatch(/tick\(\)\.then\(\(\) => terminal\?\.focus\(\)\)/);
    expect(pane).toMatch(/wantSideFocus = tab;\s*await tick\(\);\s*focusSide\(\);/);
  });

  test("the latch is retried when a panel binds, not only when the click happens", () => {
    // Without this retry the request would wait for a click that never comes.
    expect(pane).toMatch(/\$effect\(\(\) => \{\s*notes;\s*agentsPanel;\s*terminal;\s*focusSide\(\);/);
  });

  test("both panels render through `{#await}`, so nothing mounts before its chunk arrives", () => {
    expect(pane).toMatch(/\{#await AgentsPanel\(\)\}/);
    expect(pane).toMatch(/\{#await NotesPanel\(\)\}/);
    // A failed fetch has to say so instead of leaving an empty column.
    expect(pane).toMatch(/Could not load the notes/);
    expect(pane).toMatch(/Could not load the agents panel/);
  });
});

describe("the routines board is not in the boot chunk either", () => {
  test("it is loaded on the first open of the drawer", () => {
    expect(app).toMatch(/if \(tasksOpen && !TasksPanel\) void import\("\.\/lib\/components\/TasksPanel\.svelte"\)/);
    expect(app).not.toMatch(/^\s*import TasksPanel from/m);
  });

  test("the holder never goes back to null, so the board is not rebuilt on every reopen", () => {
    // TasksPanel latches its list with `seen` precisely so that closing and reopening does not
    // rebuild every card; unmounting it would throw that away for nothing. The five modals above
    // are already shaped this way — same reason, same rule.
    expect(app).not.toMatch(/TasksPanel = null/);
    expect(app).toMatch(/\{#if TasksPanel\}<TasksPanel open=\{tasksOpen\}/);
  });
});
